//! The editor's CSS data (`data/css.data`, generated by `cargo xtask web-data` from MDN's
//! public-domain data): every property with its syntax and accepted keywords, and whether
//! it is deprecated, experimental or non-standard. Embedded; parsed on first use into
//! indexes that point into the embedded text.

use std::collections::HashMap;

static DATA: &str = include_str!("../data/css.data");

#[derive(Debug, Clone, Copy)]
pub struct Property {
    pub name: &'static str,
    /// `d` deprecated, `x` experimental, `n` non-standard.
    pub flags: &'static str,
    pub syntax: &'static str,
}

#[derive(Debug, Default)]
pub struct Css {
    pub properties: Vec<Property>,
    values: HashMap<&'static str, Vec<&'static str>>,
    /// The deprecated properties (looked up for each property of each version analysed).
    deprecated: std::collections::HashSet<&'static str>,
}

impl Css {
    /// The heap it takes (its text is the binary's: only the tables).
    pub fn weight(&self) -> u64 {
        use kernel::memory::{map_bytes, vec_bytes};
        vec_bytes(&self.properties)
            + map_bytes(&self.values)
            + self.values.values().map(vec_bytes).sum::<u64>()
            + (self.deprecated.capacity() * std::mem::size_of::<&str>()) as u64
    }
}

/// The data: read on first use, let go when unused for a while (the module's
/// `release_idle`), read again when needed.
pub static CSS: kernel::cache::OnDemand<Css> = kernel::cache::OnDemand::new(load);

pub fn get() -> std::sync::Arc<Css> {
    CSS.get()
}

fn load() -> Css {
    let mut css = Css::default();
    for line in DATA.lines().filter(|l| !l.starts_with('#')) {
        let mut f = line.split('\t');
        match (f.next(), f.next(), f.next(), f.next()) {
            (Some("p"), Some(name), Some(flags), syntax) => {
                if flags.contains('d') {
                    css.deprecated.insert(name);
                }
                css.properties.push(Property { name, flags, syntax: syntax.unwrap_or("") });
            }
            (Some("v"), Some(name), Some(values), _) => {
                css.values.insert(name, values.split(' ').collect());
            }
            _ => {}
        }
    }
    css
}

impl Css {
    /// The keywords property `name` accepts (from its syntax).
    /// `name` (lowercase) is a deprecated property.
    pub fn is_deprecated(&self, name: &str) -> bool {
        self.deprecated.contains(name)
    }

    pub fn values(&self, name: &str) -> &[&'static str] {
        self.values.get(name).map_or(&[], Vec::as_slice)
    }
}

